//! Repository for ExpenseReinvoiceLink entities
//!
//! Originally generated by metaphor-schema; now **user-owned** — this exact path is declared under
//! `user_owned` in `metaphor.codegen.yaml`, so the generator skips it wholesale. The custom methods
//! below are the home for the hand-written expense-reinvoice SQL: the guarded attach, the host
//! billing adapter's pending-queue pull, and the pending → invoiced flip
//! (4-layer rule: services orchestrate and own the unit of work, repositories hold the SQL).
//!
//! `expense_id` is a LOGICAL ref to expenses.Expense — selling takes it on faith (the host
//! validates existence / company ownership / postability before calling attach); there is no
//! cross-module key and no way for this repository to verify one.
//!
//! Thin newtype over `backbone_orm::GenericCrudRepository<ExpenseReinvoiceLink, backbone_orm::SoftDelete>`.
//! All standard CRUD methods are available via `Deref`.

use anyhow::Result;
use rust_decimal::Decimal;
use sqlx::{PgPool, Row};
use uuid::Uuid;

// The optional-scalar read twin lives only in the legacy `company_scope` module. Its
// connection discipline is the request-dedicated connection when the composing service bound
// one, plain pool otherwise. The legacy task-local branch is never taken: this module sets no
// legacy scope of its own (ADR-0029).
use backbone_orm::company_scope::{fetch_all_rows_scoped, fetch_optional_scalar_scoped};
use backbone_orm::org_scope;

use crate::domain::entity::ExpenseReinvoiceLink;

/// Table name for ExpenseReinvoiceLink entities
pub const TABLE_NAME: &str = "selling.expense_reinvoice_links";

/// Repository for ExpenseReinvoiceLink entities.
///
/// All standard CRUD, soft-delete, pagination, and bulk methods are
/// provided automatically via `Deref` to `backbone_orm::GenericCrudRepository`.
pub struct ExpenseReinvoiceLinkRepository(
    backbone_orm::GenericCrudRepository<ExpenseReinvoiceLink, backbone_orm::SoftDelete>,
);

impl std::ops::Deref for ExpenseReinvoiceLinkRepository {
    type Target = backbone_orm::GenericCrudRepository<ExpenseReinvoiceLink, backbone_orm::SoftDelete>;
    fn deref(&self) -> &Self::Target { &self.0 }
}

impl ExpenseReinvoiceLinkRepository {
    /// Create a new repository instance.
    pub fn new(pool: PgPool) -> Self {
        Self(backbone_orm::GenericCrudRepository::new(pool, TABLE_NAME))
    }
}

/// One link row as the billing-adapter pull read and its DTO consume it. `state` is read as
/// `::text` (hand-written SQL never decodes a custom enum in Rust — the enum-bind lesson);
/// `created_at` comes from the audit-metadata envelope the insert trigger stamps.
pub struct ExpenseReinvoiceLinkRow {
    pub id: Uuid,
    pub order_id: Uuid,
    pub expense_id: Uuid,
    pub amount: Decimal,
    pub state: String,
    pub created_at: Option<chrono::DateTime<chrono::Utc>>,
}

/// The exact row an attach writes.
pub struct NewExpenseReinvoiceLinkRow {
    pub id: Uuid,
    pub order_id: Uuid,
    pub expense_id: Uuid,
    pub amount: Decimal,
}

/// Hand-written ExpenseReinvoiceLink SQL. Lives here (not in the write service) per the module's
/// 4-layer rule: services orchestrate and own the unit of work, repositories hold the SQL.
impl ExpenseReinvoiceLinkRepository {
    /// Attach one rebillable expense to an order. Takes the CALLER'S connection so the insert
    /// lands in the caller's transaction (the caller relays the ambient org scope onto it).
    /// `state` is pinned `'pending'` — a link starts billable and only the host billing
    /// adapter's mark moves it. Returns the raw `sqlx::Error` deliberately: the caller maps a
    /// unique violation on (order_id, expense_id) to the duplicate-refusal (the pre-read
    /// catches the common case; the partial unique index backs the race).
    pub async fn insert_link(
        &self,
        conn: &mut sqlx::PgConnection,
        l: &NewExpenseReinvoiceLinkRow,
    ) -> Result<(), sqlx::Error> {
        sqlx::query(
            r#"INSERT INTO selling.expense_reinvoice_links
                   (id, order_id, expense_id, amount, state)
               VALUES ($1,$2,$3,$4,'pending'::expense_reinvoice_state)"#,
        )
        .bind(l.id).bind(l.order_id).bind(l.expense_id).bind(l.amount)
        .execute(conn)
        .await?;
        Ok(())
    }

    /// Read the LIVE (order_id, expense_id) duplicate behind `attach_expense_reinvoice`'s
    /// pre-read. Under a composed tenancy decorator a foreign link is invisible (and could not
    /// exist — the order guard already fenced the attach).
    pub async fn find_live_link(
        &self,
        pool: &PgPool,
        order_id: Uuid,
        expense_id: Uuid,
    ) -> Result<Option<Uuid>, sqlx::Error> {
        let id: Option<Uuid> = fetch_optional_scalar_scoped(
            pool,
            sqlx::query_scalar(
                r#"SELECT id FROM selling.expense_reinvoice_links
                   WHERE order_id=$1 AND expense_id=$2
                     AND (metadata->>'deleted_at') IS NULL"#,
            )
            .bind(order_id).bind(expense_id),
        ).await?;
        Ok(id)
    }

    /// List an order's links — the host billing adapter's pull read (it filters `pending`,
    /// adds invoice lines totaling the pending amounts, then marks each link invoiced).
    /// Ordered by creation for a stable bill order; the service's order-existence probe has
    /// already fenced the read (ADR-0029).
    pub async fn list_links_for_order(
        &self,
        pool: &PgPool,
        order_id: Uuid,
    ) -> Result<Vec<ExpenseReinvoiceLinkRow>, sqlx::Error> {
        let rows = fetch_all_rows_scoped(
            pool,
            sqlx::query(
                r#"SELECT id, order_id, expense_id, amount, state::text AS st,
                          (metadata->>'created_at')::timestamptz AS created_at
                   FROM selling.expense_reinvoice_links
                   WHERE order_id=$1 AND (metadata->>'deleted_at') IS NULL
                   ORDER BY (metadata->>'created_at'), id"#,
            )
            .bind(order_id),
        ).await?;
        Ok(rows.iter().map(|r| ExpenseReinvoiceLinkRow {
            id: r.get("id"),
            order_id: r.get("order_id"),
            expense_id: r.get("expense_id"),
            amount: r.get("amount"),
            state: r.get("st"),
            created_at: r.get("created_at"),
        }).collect())
    }

    /// Flip a link pending → invoiced in ONE guarded statement. `Ok(None)` = guard refused;
    /// the caller classifies afterwards (`find_link_state`): absent/wrong-tenant vs already
    /// invoiced. NOT idempotent-by-silence — a double mark is a loud refusal (machine-verb
    /// posture), so `state='pending'` stays in the WHERE clause on purpose.
    pub async fn mark_invoiced(
        &self,
        pool: &PgPool,
        link_id: Uuid,
    ) -> Result<bool, sqlx::Error> {
        let result = org_scope::execute_scoped(
            pool,
            sqlx::query(
                r#"UPDATE selling.expense_reinvoice_links
                   SET state='invoiced'::expense_reinvoice_state
                   WHERE id=$1
                     AND state='pending'::expense_reinvoice_state
                     AND (metadata->>'deleted_at') IS NULL"#,
            )
            .bind(link_id),
        ).await?;
        Ok(result.rows_affected() > 0)
    }

    /// Post-refusal classification read for `mark_expense_reinvoice_invoiced`: the link's
    /// current state, or `None` when the id is unknown/soft-deleted (under a composed
    /// decorator also a foreign id).
    pub async fn find_link_state(
        &self,
        pool: &PgPool,
        link_id: Uuid,
    ) -> Result<Option<String>, sqlx::Error> {
        let st: Option<String> = fetch_optional_scalar_scoped(
            pool,
            sqlx::query_scalar(
                r#"SELECT state::text FROM selling.expense_reinvoice_links
                   WHERE id=$1 AND (metadata->>'deleted_at') IS NULL"#,
            )
            .bind(link_id),
        ).await?;
        Ok(st)
    }
}

backbone_core::impl_crud_repository!(ExpenseReinvoiceLinkRepository, ExpenseReinvoiceLink, soft_delete);
